(function(){"use strict";chrome.runtime.onMessage.addListener((t,r,n)=>{if(t.action==="checkGrammar"){const o=t.text;return fetch("https://api.languagetool.org/v2/check",{method:"POST",headers:{"Content-Type":"application/x-www-form-urlencoded"},body:`text=${encodeURIComponent(o)}&language=en-US`}).then(e=>e.json()).then(e=>{n({success:!0,data:e})}).catch(e=>{console.error("API Error:",e),n({success:!1,error:e.message})}),!0}})})();
